window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-36101\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύπον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 269 na letra ρ · nº geral 36101</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ῥύπος.</p></section></article>\n<article id=\"entry-dgp-36102\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύπος1, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 270 na letra ρ · nº geral 36102</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sujeira; imundície 2 nódoa 3 cera para lacrar; lacre.</p></section></article>\n<article id=\"entry-dgp-36103\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύπος2, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 271 na letra ρ · nº geral 36103</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Medic. soro de leite; almece.</p></section></article>\n<article id=\"entry-dgp-36104\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυπόω1-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 272 na letra ρ · nº geral 36104</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. perf. pas. ῥερυπωμένος) sujar; enodoar; manchar (a veste).</p></section></article>\n<article id=\"entry-dgp-36105\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυπόω2</h1><div class=\"entry-meta\"><span>DGP · ordem 273 na letra ρ · nº geral 36105</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = ῥυπάω.</p></section></article>\n<article id=\"entry-dgp-36106\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυπτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 274 na letra ρ · nº geral 36106</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">próprio para lavar; eficaz para lavar. 〈ῥύπτω〉</p></section></article>\n<article id=\"entry-dgp-36107\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 275 na letra ρ · nº geral 36107</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lavar; limpar ♦ méd. pas. ῥύπτομαι (impf. ἐρρυπ­τόμην, aor. ἐρρυψάμην) 2 lavar-se; limpar-se. 〈ῥύπος〉</p></section></article>\n<article id=\"entry-dgp-36108\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυσάμην</h1><div class=\"entry-meta\"><span>DGP · ordem 276 na letra ρ · nº geral 36108</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1ª sing. aor., ῥυσάσθην 3ª dual aor., ῥύσατο 3ª sing. aor., ῥύσθαι inf. pres., de ῥύομαι.</p></section></article>\n<article id=\"entry-dgp-36109\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυσιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 277 na letra ρ · nº geral 36109</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. pas. ἐρρυσιάσθην) 1 tirar à força; arrancar; arrebatar 2 pilhar; saquear 3 tomar como garantia, como penhor 4 tomar em represália. 〈ῥύσιον〉</p></section></article>\n<article id=\"entry-dgp-36110\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυσίβωμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 278 na letra ρ · nº geral 36110</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">protetor dos altares. 〈ῥύομαι, βωμός〉</p></section></article>\n<article id=\"entry-dgp-36111\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύσιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 279 na letra ρ · nº geral 36111</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ῥύσιος.</p></section></article>\n<article id=\"entry-dgp-36112\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύσιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 280 na letra ρ · nº geral 36112</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que libera; que salva; que protege; defensor ♦ τὸ ῥύσιον 2 despojo; presa; butim 3 presa tomada em represália; compensação 4 garantia 5 represália; multa; castigo contra alguém, dat. 6 satisfação; direito de represália contra, κατά e gen. 7 pl. liberação 8 pl. oferendas para a salvação. 〈ῥύομαι〉</p></section></article>\n<article id=\"entry-dgp-36113\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυσίπολις, εως</h1><div class=\"entry-meta\"><span>DGP · ordem 281 na letra ρ · nº geral 36113</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) protetor ou defensor da cidade. 〈ῥύομαι, πόλις〉</p></section></article>\n<article id=\"entry-dgp-36114\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 282 na letra ρ · nº geral 36114</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 escoamento (de líquido); escorrimento (de sangue); corrente; curso (de rio) 2 Medic. fluxo menstrual 3 bíbl. gonorréia 4 queda (de frutos, de cabelos) 5 transitoriedade; instabilidade 6 produto; produção (da oliveira). 〈ῥέω〉</p></section></article>\n<article id=\"entry-dgp-36115\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυσμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 283 na letra ρ · nº geral 36115</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ῥυθμός.</p></section></article>\n<article id=\"entry-dgp-36116\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυσός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 284 na letra ρ · nº geral 36116</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 enrugado; rugoso 2 de cenho franzido (expr. de aborrecimento); aborrecido 3 encarquilhado; decrépito.</p></section></article>\n<article id=\"entry-dgp-36117\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυσότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 285 na letra ρ · nº geral 36117</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">testa enrugada; rugosidade. 〈ῥυσός〉</p></section></article>\n<article id=\"entry-dgp-36118\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυστάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 286 na letra ρ · nº geral 36118</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 puxar; arrastar 2 violentar; ultrajar; maltratar. 〈ῥύομαι〉</p></section></article>\n<article id=\"entry-dgp-36119\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυστακτύς, ύος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 287 na letra ρ · nº geral 36119</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">safanão; maus tratos; violência. 〈ῥυστάζω〉</p></section></article>\n<article id=\"entry-dgp-36120\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύστης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 288 na letra ρ · nº geral 36120</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">libertador. 〈ῥύομαι〉</p></section></article>\n<article id=\"entry-dgp-36121\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυτήρ1, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 289 na letra ρ · nº geral 36121</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 quem lança flechas; flecheiro; seteiro 2 pl. rédeas de cavalo; tirante de carro 3 correia; corda 4 chicote. 〈ῥυτός〉</p></section></article>\n<article id=\"entry-dgp-36122\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυτήρ2, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 290 na letra ρ · nº geral 36122</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">protetor; liberador; salvador. 〈ῥύομαι〉</p></section></article>\n<article id=\"entry-dgp-36123\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυτιδόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 291 na letra ρ · nº geral 36123</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ῥυτιδώσω, part. perf. pas. ἐρρυτιδωμέ­νος) 1 fazer enrugar; tornar rugoso 2 intr. ser enrugado; enrugar; contrair-se ♦ pas. 3 enrugar-se. 〈ῥυτίς〉</p></section></article>\n<article id=\"entry-dgp-36124\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυτίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 292 na letra ρ · nº geral 36124</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prega da pele; ruga. 〈ῥύομαι〉</p></section></article>\n<article id=\"entry-dgp-36125\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυτός1, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 293 na letra ρ · nº geral 36125</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que corre; corrente; fluente; fluido; líquido ♦ τὸ ῥυτόν 2 copo em forma de chifre. 〈ῥέω〉</p></section></article>\n<article id=\"entry-dgp-36126\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυτός2, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 294 na letra ρ · nº geral 36126</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 puxado; arrastado ♦ τὰ ῥυτά 2 rédeas. 〈ῥύομαι〉</p></section></article>\n<article id=\"entry-dgp-36127\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύτωρ, ορος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 295 na letra ρ · nº geral 36127</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lançador; atirador de flechas (Apolo) 2 protetor; defensor 3 defesa; proteção.</p></section></article>\n<article id=\"entry-dgp-36128\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυῶ, ῆς, ῆ</h1><div class=\"entry-meta\"><span>DGP · ordem 296 na letra ρ · nº geral 36128</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. aor.2 de ῥέω.</p></section></article>\n<article id=\"entry-dgp-36129\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 297 na letra ρ · nº geral 36129</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indecl. (τό) rô, letra do alfabeto grego.</p></section></article>\n<article id=\"entry-dgp-36130\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥωγαλέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 298 na letra ρ · nº geral 36130</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 despedaçado; dilacerado; estraçalhado 2 lacerado; sulcado (terra). 〈ῥήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-36131\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥωγάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 299 na letra ρ · nº geral 36131</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 despedaçado; lacerado 2 fendido; cortado verticalmente; despenhado (pedra) 3 triturado; quebrado. 〈ῥώξ〉</p></section></article>\n<article id=\"entry-dgp-36132\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥωγμή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 300 na letra ρ · nº geral 36132</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rachadura; fenda; fissura 2 Medic. fratura. 〈ῥήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-36133\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥώθων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 301 na letra ρ · nº geral 36133</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 nariz; narina 2 pl. narinas. Ῥώμα, ας (ἡ) dór. = Ῥώμη2. Ῥωμαϊκός, ή, όν 1 que concerne aos romanos; dos romanos; romano; latino. 〈 Ῥώμη〉</p></section></article>\n<article id=\"entry-dgp-36134\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥωμαικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 302 na letra ρ · nº geral 36134</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 à moda romana 2 em latim. Ῥωμαῖος, α, ον 1 de Roma; romano ♦ ὁ Ῥωμαῖος 2 o mês romano; novembro 3 pl. os romanos ♦ τὰ Ῥωμαῖα 4 os jogos romanos. 〈 Ῥώμη〉</p></section></article>\n<article id=\"entry-dgp-36135\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥωμαϊστί</h1><div class=\"entry-meta\"><span>DGP · ordem 303 na letra ρ · nº geral 36135</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em língua romana; em latim. 〈 Ῥωμαῖος〉</p></section></article>\n<article id=\"entry-dgp-36136\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥωμαλέος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 304 na letra ρ · nº geral 36136</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 forte; robusto; sólido (coisa) 2 forte; robusto (pessoa). 〈ῥώμη〉</p></section></article>\n<article id=\"entry-dgp-36137\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥώμη1, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 305 na letra ρ · nº geral 36137</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 força física; vigor; robustez 2 força; potência; poder financeiro (de uma cidade) 3 Mil. força militar; exército; marinha 4 força; poder (de arma, da palavra); intensidade (dos prazeres) 5 força; firmeza de alma, de espírito ♦ Ῥώμη 5 Rome, n. de cadela. Ῥώμη2, ης (ἡ) 1 Roma, cidade 2 Roma, n. de m. [lat.] Ῥωμινάλιος ἐρινεός (ὁ) a figueira do Ruminal, em Roma.</p></section></article>\n<article id=\"entry-dgp-36138\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥώννυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 306 na letra ρ · nº geral 36138</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐρρώννυν, aor. ἔρρωνα, fut. e perf. desus.; pas. ῥώννυμαι, fut. ῥωσθήσομαι, aor. ἐρρώσθην, perf. ἔρρωμαι com sent. de pres., m.-q.-perf. ἐρρώμην com sent. de impf.) 1 tornar forte; fortificar; reforçar ♦ méd. pas. 2 estar em plena força; ser forte, vigoroso, poderoso 3 estar pronto, em condições de; estar impaciente ou desejoso de, εἰς, πρός e ac. ou inf. 4 estar em boas condições de saúde; estar bem 5 reunir todas as suas forças para um empreendimento; fortificar-se; endurecer-se; fórm. de despedida nas cartas, ἔρρωσο passe bem! ἐρρῶσθαί τινι φράζειν ou εἰπεῖν plat. saudar alguém, às vezes iron., mandar passear.</p></section></article>\n<article id=\"entry-dgp-36139\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥώξ1, ῥωγός (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 307 na letra ρ · nº geral 36139</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fenda; passagem estreita; abertura 2 fragmento 3 teia de aranha. 〈ῥήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-36140\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥώξ2, ῥωγός (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 308 na letra ρ · nº geral 36140</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">grão ou semente de uva; uva. 〈ῥάξ〉</p></section></article>\n<article id=\"entry-dgp-36141\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥώομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 309 na letra ρ · nº geral 36141</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐρρωόμην, fut. ρώσομαι, aor. ἐρρωσάμην, perf. desus.) 1 (cabelo, perna) agitar-se com força; sacudir-se 2 (guerreiro, dançarina) mover-se vigorosamente; mexer-se 3 ser pressuroso; apressar-se em benefício de alguém, dat.</p></section></article>\n<article id=\"entry-dgp-36142\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥωπήιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 310 na letra ρ · nº geral 36142</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. matagal; arbustos; sarças. 〈ῥώψ〉</p></section></article>\n<article id=\"entry-dgp-36143\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥωπικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 311 na letra ρ · nº geral 36143</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 miúdo; de pouco valor; insignificante ♦ τὰ ῥωπικά 2 mercadorias ou objetos de pouco valor. 〈ῥῶπος〉</p></section></article>\n<article id=\"entry-dgp-36144\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥωπογραφία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 312 na letra ρ · nº geral 36144</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pintura de pequenos objetos; natureza morta. 〈ῥῶπος, γράφω〉</p></section></article>\n<article id=\"entry-dgp-36145\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥωποπερπερήθρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 313 na letra ρ · nº geral 36145</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tagarelice; fanfarronice. 〈ῥῶ­πος, πέρπερος〉</p></section></article>\n<article id=\"entry-dgp-36146\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥῶπος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 314 na letra ρ · nº geral 36146</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mercadoria miúda; mercadoria de pouco valor; ninharia 2 pintura de pequenas coisas, de mau gosto. 〈ῥώψ〉</p></section></article>\n<article id=\"entry-dgp-36147\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥωχμός1, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 315 na letra ρ · nº geral 36147</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fenda; greta; rachadura. 〈ῥήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-36148\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥωχμός2, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 316 na letra ρ · nº geral 36148</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 arroto 2 ronco. 〈ῥώχω〉</p></section></article>\n<article id=\"entry-dgp-36149\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥώχω</h1><div class=\"entry-meta\"><span>DGP · ordem 317 na letra ρ · nº geral 36149</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) tard. roncar.</p></section></article>\n<article id=\"entry-dgp-36150\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥώψ, ῥωπός (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 318 na letra ρ · nº geral 36150</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. silvado; matagal; urze.</p></section></article>\n<article id=\"entry-dgp-36151\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σ, σ, ς (σίγμα</h1><div class=\"entry-meta\"><span>DGP · ordem 1 na letra σ · nº geral 36151</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ou σῖγμα) (τό) 1 sigma, 18ª letra do alfabeto grego ♦ num. 2 σʹ = 200 ou 200º 3 ͵σ = 200.000 ou 200.000º.</p></section></article>\n<article id=\"entry-dgp-36152\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σ᾽</h1><div class=\"entry-meta\"><span>DGP · ordem 2 na letra σ · nº geral 36152</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">σέ e, rar., σοι, ou σά em elisão.</p></section></article>\n<article id=\"entry-dgp-36153\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σά</h1><div class=\"entry-meta\"><span>DGP · ordem 3 na letra σ · nº geral 36153</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. n. ou dual fem. de σός, σή, σόν.</p></section></article>\n<article id=\"entry-dgp-36154\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σᾶ</h1><div class=\"entry-meta\"><span>DGP · ordem 4 na letra σ · nº geral 36154</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. n. de σάος.</p></section></article>\n<article id=\"entry-dgp-36155\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαβάζιος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5 na letra σ · nº geral 36155</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Sabázio, divindade frígia cujos mistérios se identificavam com as τελεταί de Dioniso 2 Sa­bázio, denominação de Dioniso ♦ adj. 3 de Sabázio; de Dioniso; báquico.</p></section></article>\n<article id=\"entry-dgp-36156\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαββατίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 6 na letra σ · nº geral 36156</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. σαββατιῶ e σαββατίσω, aor. ἐσαββάτισα, perf. σεσαββάτικα) 1 bíbl. guardar, observar o sábado 2 crist. ter um dia de repouso. 〈σάββατον〉</p></section></article>\n<article id=\"entry-dgp-36157\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαββατισμός, οῦ (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 7 na letra σ · nº geral 36157</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 repouso ou observância do sábado 2 crist. repouso. 〈σάββατον〉</p></section></article>\n<article id=\"entry-dgp-36158\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάββατον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 8 na letra σ · nº geral 36158</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 Sábado, dia do descanso, entre os hebreus 2 bíbl. período de sete dias; semana. [hebr.]</p></section></article>\n<article id=\"entry-dgp-36159\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαβοῖ</h1><div class=\"entry-meta\"><span>DGP · ordem 9 na letra σ · nº geral 36159</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. Σαβός.</p></section></article>\n<article id=\"entry-dgp-36160\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σάβος</h1><div class=\"entry-meta\"><span>DGP · ordem 10 na letra σ · nº geral 36160</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Σαβός, οῦ (ὁ) 1 Sabázio, divindade frígia identificada com Dioniso 2 pl. fiéis que se dedicam ao culto de Sabázio: εὐοῖ σαβοῖ dem. evoé fiéis sabázios!, i.e., fiéis bacantes (cf. Σαβάζιος).</p></section></article>\n<article id=\"entry-dgp-36161\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάγαρις, εως,</h1><div class=\"entry-meta\"><span>DGP · ordem 11 na letra σ · nº geral 36161</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. ιος (ἡ) espécie de machado de um ou dois gumes utilizado pelas amazonas, pelos persas e pelos citas.</p></section></article>\n<article id=\"entry-dgp-36162\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάγη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 12 na letra σ · nº geral 36162</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 equipamento; bagagem; fardo 2 sacola; mochila 3 armadura 4 arreios de animal de carga; albarda; sela.</p></section></article>\n<article id=\"entry-dgp-36163\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαγηνεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 13 na letra σ · nº geral 36163</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">caça ou pesca com rede. 〈σαγηνεύω〉</p></section></article>\n<article id=\"entry-dgp-36164\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαγηνεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 14 na letra σ · nº geral 36164</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. = σαγηνευτής.</p></section></article>\n<article id=\"entry-dgp-36165\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαγηνευτής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 15 na letra σ · nº geral 36165</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. pescador que pesca com rede de arrastão. 〈σαγηνεύω〉</p></section></article>\n<article id=\"entry-dgp-36166\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαγηνεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 16 na letra σ · nº geral 36166</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pescar com rede de arrastão; pescar 2 fazer o cerco de um local; invadir 3 capturar alguém. 〈σαγήνη〉</p></section></article>\n<article id=\"entry-dgp-36167\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαγήνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 17 na letra σ · nº geral 36167</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 grande rede de pesca de arrastão 2 rede de caça.</p></section></article>\n<article id=\"entry-dgp-36168\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 18 na letra σ · nº geral 36168</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ger. pl. vestimenta; manto 2 estojo de escudo 3 carga; bagagem; bagagem de equipamentos 4 armadura 5 arreios de animal de carga; albarda; sela 6 pilha; montão.</p></section></article>\n<article id=\"entry-dgp-36169\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάγος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 19 na letra σ · nº geral 36169</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 saio, veste dos gauleses e iberos 2 manto; capa de soldado, de tecido rústico.</p></section></article>\n<article id=\"entry-dgp-36170\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαδδουκαῖος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 20 na letra σ · nº geral 36170</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. saduceu, membro de uma seita judaica.</p></section></article>\n<article id=\"entry-dgp-36171\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαδυάττης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 21 na letra σ · nº geral 36171</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Sadiates, rei da Lídia.</p></section></article>\n<article id=\"entry-dgp-36172\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαθρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 22 na letra σ · nº geral 36172</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 avariado; danificado 2 rachado; trincado (vaso) 3 Medic. doente; malsão 4 fraco; em mau estado; inconsistente 5 de má qualidade; de baixa condição; mau ♦ σαθρόν adv. 6 de modo defeituoso: σ. φθέγγεσθαι plat. emitir som desarmonioso, σαθρὸν ὑπηχεῖν plut. (bajulação) soar falso.</p></section></article>\n<article id=\"entry-dgp-36173\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 23 na letra σ · nº geral 36173</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. σανῶ, aor. ἔσηνα, perf. desus.; fut. pas. σαν­θήσομαι) 1 agitar a cauda em sinal de alegria: σ. ἀμφί τινα hom. girar à volta de alguém balançando a cauda, σ. οὐρῇ hom. balançar a cauda 2 acolher com demonstrações de alegria; fazer festas a algo ou alguém 3 afagar; acariciar; adular: σ. μόρον ésql. adular a morte para comovê-la, παιδός με σαίνει φθόγγος sóf. a voz de meu filho afaga meus ouvidos 4 acalmar (a dor) 5 enganar; seduzir; iludir, ac. ♦ pas. 6 bíbl. inquietar-se; perturbar-se: σαίνεσθαι ἐν ταῖς θλίψεσιν N.T. perturbar-se nas aflições.</p></section></article>\n<article id=\"entry-dgp-36174\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαίρω1</h1><div class=\"entry-meta\"><span>DGP · ordem 24 na letra σ · nº geral 36174</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. σαρῶ, aor. ἔσηρα) 1 varrer; limpar varrendo 2 remover varrendo (poeira).</p></section></article>\n<article id=\"entry-dgp-36175\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαίρω2</h1><div class=\"entry-meta\"><span>DGP · ordem 25 na letra σ · nº geral 36175</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só perf. com sent. de pres. σέσηρα, part. σεσηρώς) 1 ranger ou mostrar os dentes como sinal de raiva 2 mostrar os dentes em riso escancarado: σεσηρότι γέλωτι luc. com um riso escancarado ♦ σεσηρός adv. 3 de modo galhofeiro; com zombaria: σεσηρὸς αἰκάλλειν bábrio lisonjear com zombaria.</p></section></article>\n<article id=\"entry-dgp-36176\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σάϊς, εως,</h1><div class=\"entry-meta\"><span>DGP · ordem 26 na letra σ · nº geral 36176</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn ϊος (ἡ) Sais, cidade do Egito.</p></section></article>\n<article id=\"entry-dgp-36177\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαΐτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 27 na letra σ · nº geral 36177</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">originário ou habitante de Sais; saíta. 〈Σάϊς〉</p></section></article>\n<article id=\"entry-dgp-36178\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαϊτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 28 na letra σ · nº geral 36178</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Sais; saítico. 〈Σάϊς〉</p></section></article>\n<article id=\"entry-dgp-36179\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σακέσπαλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 29 na letra σ · nº geral 36179</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que agita o escudo; belicoso. 〈σάκος, πάλλω〉</p></section></article>\n<article id=\"entry-dgp-36180\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σακεσφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 30 na letra σ · nº geral 36180</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">porta-escudo. 〈σάκος, φέρω〉</p></section></article>\n<article id=\"entry-dgp-36181\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάκιον</h1><div class=\"entry-meta\"><span>DGP · ordem 31 na letra σ · nº geral 36181</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = σακκίον.</p></section></article>\n<article id=\"entry-dgp-36182\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σακκέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 32 na letra σ · nº geral 36182</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filtrar; coar. 〈σάκκος〉</p></section></article>\n<article id=\"entry-dgp-36183\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάκκιον,</h1><div class=\"entry-meta\"><span>DGP · ordem 33 na letra σ · nº geral 36183</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. σάκιον, ου (τό) 1 saco pequeno 2 manto grosseiro; cilício. 〈σάκκος〉</p></section></article>\n<article id=\"entry-dgp-36184\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάκκος,</h1><div class=\"entry-meta\"><span>DGP · ordem 34 na letra σ · nº geral 36184</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. σάκος, ου (ὁ) 1 tecido grosseiro de pelo de cabra 2 bíbl. cilício 3 saco; bolsa 4 filtro; coador; peneira 5 barba descuidada, longa e espessa.</p></section></article>\n<article id=\"entry-dgp-36185\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σακκοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 35 na letra σ · nº geral 36185</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que veste manto grosseiro. 〈σάκκος, φέρω〉</p></section></article>\n<article id=\"entry-dgp-36186\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάκος1, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 36 na letra σ · nº geral 36186</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 escudo de vime ou de madeira recoberto com couro de boi ou com uma placa de metal 2 escudo; proteção; defesa.</p></section></article>\n<article id=\"entry-dgp-36187\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάκος2</h1><div class=\"entry-meta\"><span>DGP · ordem 37 na letra σ · nº geral 36187</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = σάκκος.</p></section></article>\n<article id=\"entry-dgp-36188\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάκτας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 38 na letra σ · nº geral 36188</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">saco. 〈σάττω〉</p></section></article>\n<article id=\"entry-dgp-36189\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάκτωρ, ορος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 39 na letra σ · nº geral 36189</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que enche, que amontoa: σ. Ἅιδου ésql. provedor dos infernos, ref. à morte.</p></section></article>\n<article id=\"entry-dgp-36190\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαλάκων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 40 na letra σ · nº geral 36190</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que requebra ao andar, que se apresenta com grandes ares; pomposo; fanfarrão. 〈σάλος〉</p></section></article>\n<article id=\"entry-dgp-36191\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαλαμάνδρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 41 na letra σ · nº geral 36191</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">salamandra, lagarto.</p></section></article>\n<article id=\"entry-dgp-36192\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλαμίν</h1><div class=\"entry-meta\"><span>DGP · ordem 42 na letra σ · nº geral 36192</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Σαλαμίς.</p></section></article>\n<article id=\"entry-dgp-36193\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλαμινιάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 43 na letra σ · nº geral 36193</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) = Σαλαμίνιος.</p></section></article>\n<article id=\"entry-dgp-36194\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλαμίνιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 44 na letra σ · nº geral 36194</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da ilha de Salamina; salamínio ♦ οἱ Σαλαμίνιοι 2 os habitantes de Salamina ♦ ἡ Σαλαμινία 3 a nau Salamínia, embarcação ateniense para o transporte de cortejos e procissões.</p></section></article>\n<article id=\"entry-dgp-36195\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλαμίς, ῖνος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 45 na letra σ · nº geral 36195</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Salamina, n. de ilha do golfo Sarônico e de cidade de Chipre.</p></section></article>\n<article id=\"entry-dgp-36196\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαλεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 46 na letra σ · nº geral 36196</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. σαλεύσω, aor. ἐσάλευσα, perf. desus.; pas. fut. σαλευθήσομαι, aor. ἐσαλεύθην, perf. σεσάλευμαι) 1 agitar; sacudir; abalar: σ. πτέρυγα eur. bater asas, σ. πέδον licofr. abalar o solo, σ. τινὰ ἐν θεμελίων sept. abalar alguém em seus fundamentos 2 pôr em agitação; incitar; sublevar (povo) 3 pôr em movimento; fazer mudar de lugar (cavalo) 4 sacudir para comprimir; encher completamente (uma medida) 5 apoiar; ancorar algo, ac., em, e dat.: σαλεύω ἐπὶ αὐτῇ τὸν βίον hel. ancoro nela a minha vida 6 intr. (navio) chacoalhar; balançar; oscilar 7 intr. balançar-se ao andar; vacilar; pavonear-se 8 (navio ancorado) estar agitado por um movimento balouçante; estar ancorado 9 (pessoa) apoiar-se em, ἐπί e ac.: σ. ἐπὶ τῶν ἐλπίδων hel. apoiar-se nas esperanças 10 (discurso, conversa) versar sobre, ἐν e dat. 〈σάλος〉</p></section></article>\n<article id=\"entry-dgp-36197\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλμώνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 47 na letra σ · nº geral 36197</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Salmona, cidade da Élida.</p></section></article>\n<article id=\"entry-dgp-36198\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλμώνιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 48 na letra σ · nº geral 36198</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Salmônio, promontório de Creta.</p></section></article>\n<article id=\"entry-dgp-36199\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλμονίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 49 na letra σ · nº geral 36199</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) de Salmônio. 〈Σαλμώνιον〉</p></section></article>\n<article id=\"entry-dgp-36200\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 50 na letra σ · nº geral 36200</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 agitação do solo; tremor de terra; abalo 2 agitação de ondas; ondas do mar encrespado 3 ancoradouro 4 balanço do navio ancorado 5 agitação; movimentação 6 perturbação; aflição; inquietação.</p></section></article>\n";
